-- Experimental, exact expired-lease phase repair. It does not rearm or write Sheets.
CREATE TABLE IF NOT EXISTS continuous_expired_revoke_phase_evidence (
 operation_token TEXT PRIMARY KEY, spreadsheet_id TEXT NOT NULL, epoch_id TEXT NOT NULL,
 transition_id TEXT NOT NULL, expense_id TEXT NOT NULL, source_version INTEGER NOT NULL,
 source_revision INTEGER NOT NULL, source_digest TEXT NOT NULL, notice_stamp TEXT NOT NULL,
 notice_identity TEXT NOT NULL, sheet_id INTEGER NOT NULL, sheet_name TEXT NOT NULL,
 row_number INTEGER NOT NULL, postimage TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TRIGGER IF NOT EXISTS continuous_expired_revoke_phase_evidence_insert BEFORE INSERT ON continuous_expired_revoke_phase_evidence
WHEN NOT EXISTS(SELECT 1 FROM stable_workbook_claims c JOIN stable_recovery_epochs e ON e.spreadsheet_id=c.spreadsheet_id AND e.epoch_id=NEW.epoch_id AND e.state='REVIEW' AND e.target_type='EXPENSE' AND e.target_key=NEW.expense_id AND e.target_version=NEW.source_version JOIN continuous_normal_recovery_admissions a ON a.epoch_id=e.epoch_id AND a.spreadsheet_id=e.spreadsheet_id AND a.expense_id=e.target_key AND a.source_version=e.target_version JOIN stable_recovery_operations o ON o.epoch_id=e.epoch_id AND o.operation_token=c.operation_token AND o.state='ADMITTED' JOIN sync_jobs j ON j.entity_type='EXPENSE' AND j.entity_key=e.target_key AND j.entity_version=e.target_version AND j.status='REVIEW' AND j.last_error='CONTINUOUS_SYNC_LEASE_EXPIRED_UNCERTAIN' AND j.lease_until IS NOT NULL AND j.lease_until<=strftime('%Y-%m-%dT%H:%M:%fZ','now') JOIN expense_events src ON src.expense_id=j.entity_key AND src.version=j.entity_version AND src.status='CANCELLED' JOIN continuous_publication_intents i ON i.transition_id=NEW.transition_id AND i.spreadsheet_id=e.spreadsheet_id AND i.entity_id=e.target_key AND i.source_version=e.target_version AND i.claim_token=c.operation_token AND i.lease_token=j.lease_token AND i.kind='REVOKE' AND i.state='IN_FLIGHT' AND i.source_digest=NEW.source_digest AND i.sheet_id=NEW.sheet_id AND i.sheet_name=NEW.sheet_name AND i.row_number=NEW.row_number AND i.after_value=NEW.postimage JOIN stable_source_revision r ON r.singleton=1 AND r.revision=NEW.source_revision JOIN continuous_revoke_review_close_activation active ON active.singleton=1 WHERE c.spreadsheet_id=NEW.spreadsheet_id AND c.operation_token=NEW.operation_token AND c.state='REVIEW' AND c.phase IS NULL AND c.review_reason='CONTINUOUS_SYNC_LEASE_EXPIRED_UNCERTAIN' AND c.notice_stamp=NEW.notice_stamp AND c.notice_identity=NEW.notice_identity AND length(c.notice_stamp)>0 AND length(c.notice_identity)>0 AND NOT EXISTS(SELECT 1 FROM failed_jobs f WHERE f.queue_name='malipang-jobs' AND f.job_key='EXPENSE:'||e.target_key||':'||e.target_version AND f.status='OPEN' AND f.error='DEAD_LETTER_MAX_RETRIES'))
BEGIN SELECT RAISE(ABORT,'expired revoke phase requires exact positive evidence'); END;
CREATE TRIGGER IF NOT EXISTS continuous_expired_revoke_phase_evidence_no_update BEFORE UPDATE ON continuous_expired_revoke_phase_evidence BEGIN SELECT RAISE(ABORT,'expired revoke phase evidence immutable'); END;
CREATE TRIGGER IF NOT EXISTS continuous_expired_revoke_phase_evidence_no_delete BEFORE DELETE ON continuous_expired_revoke_phase_evidence BEGIN SELECT RAISE(ABORT,'expired revoke phase evidence retained'); END;
CREATE TRIGGER IF NOT EXISTS continuous_expired_revoke_phase_evidence_no_replace BEFORE INSERT ON continuous_expired_revoke_phase_evidence WHEN EXISTS(SELECT 1 FROM continuous_expired_revoke_phase_evidence WHERE operation_token=NEW.operation_token OR rowid=NEW.rowid) BEGIN SELECT RAISE(ABORT,'expired revoke phase evidence collision'); END;
